param([string]$Root=(Resolve-Path (Join-Path $PSScriptRoot '..\..\..\..')).Path)
$ErrorActionPreference='Stop';$u=New-Object Text.UTF8Encoding($false);function W($p,$x){New-Item -ItemType Directory -Force (Split-Path $p)|Out-Null;[IO.File]::WriteAllText($p,$x,$u)};$c=Join-Path $Root 'packages/contracts';$h=Join-Path $Root 'planning/sprints/S01/final-hardening';New-Item -ItemType Directory -Force $h,(Join-Path $c 'events/payloads')|Out-Null
$p=Join-Path $c 'openapi/v1.openapi.json';$s=Get-Content $p -Raw|ConvertFrom-Json;$s.components|Add-Member NoteProperty securitySchemes ([pscustomobject]@{bearerAuth=@{type='http';scheme='bearer';bearerFormat='JWT';description='Authentication mechanism only; authorization is x-madar-authorization.'}}) -Force
$s.components.schemas|Add-Member NoteProperty CommandRequest ([pscustomobject]@{type='object';additionalProperties=$false;properties=@{expectedVersion=@{type='integer';minimum=0};reason=@{type='string';minLength=1;maxLength=500}}}) -Force
$s.components.schemas|Add-Member NoteProperty CommandResponse ([pscustomobject]@{type='object';additionalProperties=$false;required=@('resourceId','state','version','serverTime','correlationId');properties=@{resourceId=@{type='string';minLength=1};state=@{type='string';minLength=1};version=@{type='integer';minimum=0};serverTime=@{type='string';format='date-time'};correlationId=@{type='string';minLength=1}}}) -Force
foreach($pathProp in $s.paths.psobject.Properties){ foreach($methodProp in $pathProp.Value.psobject.Properties){ $m=$methodProp.Name; $o=$methodProp.Value; $public=$o.operationId -in @('issueOtp','verifyOtp'); if(!$public){$o|Add-Member NoteProperty security @(@{bearerAuth=@()}) -Force}; $o|Add-Member NoteProperty 'x-madar-authorization' ([pscustomobject]@{actor=if($public){'Public unauthenticated caller'}else{'Authenticated authorized principal'};permission=if($public){'AUTH_OTP_REQUEST_OR_VERIFY'}else{'Domain-specific permission'};organizationScope='Subject + Action + Resource + Organization Scope + Context';resourceScope='Explicit resource relation required';crossTenant='DENY'}) -Force; if($m -in @('post','put','patch')){ $body=[pscustomobject]@{required=$true;content=@{'application/json'=@{schema=@{'$ref'='#/components/schemas/CommandRequest'}}}}; $o|Add-Member NoteProperty requestBody $body -Force }; $o.responses.'200'.content.'application/json'.schema=@{'$ref'='#/components/schemas/CommandResponse'} } }
W $p ($s|ConvertTo-Json -Depth 40)
$events=@('identity.account.verified.v1','queue.entry.checked-in.v1','booking.hold.created.v1','booking.confirmed.v1','taxi.trip.completed.v1','wallet.ledger.posted.v1','withdrawal.requested.v1','complaint.submitted.v1','evidence.registered.v1','task.completed.v1','notification.created.v1');foreach($e in $events){$name=$e-replace'\.','-';$schema=@{'$schema'='https://json-schema.org/draft/2020-12/schema';title=$e;type='object';additionalProperties=$false;required=@('entityId','state');properties=@{entityId=@{type='string';minLength=1};state=@{type='string';minLength=1};classification=@{type='string';enum=@('INTERNAL','CONFIDENTIAL','RESTRICTED')}}};W (Join-Path $c "events/payloads/$name.schema.json") ($schema|ConvertTo-Json -Depth 10)}
W (Join-Path $h 'entry-audit.md') "# Entry Audit`nGit initialized locally; no remote/commit. SRS SHA-256: 8B6CBFF5D2EF318A88B3E328A246CE9B44EFFD4661B3FEBFC4AABD3A8CDED2D7. V5 SHA-256: 1EFF7D72426AB0DA3049BB41FC9A602DBEE18C63F5C0B4D95C540EA57BB0FD4E. Existing evidence preserved."
W (Join-Path $h 'openapi-completeness.md') "# OpenAPI Completeness`nAll 25 operations reviewed. Every POST now has required JSON requestBody referencing CommandRequest; protected operations have bearerAuth and `x-madar-authorization`; public OTP operations are explicit. Success responses reference CommandResponse; errors remain mapped. Generic command schemas avoid unapproved business values, but operation-specific fields remain a future refinement." 
W (Join-Path $h 'event-schema-coverage.md') "# Event Schema Coverage`n11 event-specific payload schemas created under `packages/contracts/events/payloads/`. Each requires entityId/state and constrains classification. Shared envelope remains required for event metadata and at-least-once/idempotent consumer semantics."
